/// <summary>
/// Find record
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <param name = "_update">treu or false</param>
/// <returns>Record</returns>
static public NDXMultipleS_CustTable find(InventTable _inventTable, boolean _update = false)
{
    NDXMultipleS_CustTable lNDXMultipleS_CustTable;

    if(_inventTable)
    {
        lNDXMultipleS_CustTable.selectForUpdate(_update);

        select lNDXMultipleS_CustTable
            where lNDXMultipleS_CustTable.RefRecId_InventTable == _inventTable.RecId;
    }

    return lNDXMultipleS_CustTable;
}

/// <summary>
/// Checks if validity check is availabe
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <returns>true or false</returns>
static public boolean hasValidityCheck(InventTable _inventTable)
{
    return NDXMultipleS_CustTable::find(_inventTable).RecId > 0;
}

/// <summary>
/// Gets all all valid customer ids for an item
/// </summary>
/// <param name = "_itemRecId">_itemRecId</param>
/// <returns>String of customer ids></returns>
static str Range2String(RecId _itemRecId)
{
    #define.Comma(' ,')

    NDXMultipleS_CustTable  nDX_MultipleS_Customer;
    CustTable lCustTable;
    str range2String;
    boolean                 lFirst = true;
    ;
    while select nDX_MultipleS_Customer
        where nDX_MultipleS_Customer.RefRecId_InventTable == _itemRecId
        join lCustTable
            where lCustTable.RecId == nDX_MultipleS_Customer.RefRecId_CustTable
    {
        if (!lFirst)
        {
            range2String += #Comma;
        }
        else
        {
            lFirst = false;
        }

        range2String += lCustTable.AccountNum;
    }
    return range2String;
}

public void insert()
{
    NDXMultipleS_CustTable orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void update()
{
    NDXMultipleS_CustTable orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void delete()
{
    NDXMultipleS_CustTable orig = this.orig();
    super();
    this.writeLog(orig, null);
}

private void writeLog(NDXMultipleS_CustTable _orig, NDXMultipleS_CustTable _current)
{
    NDXMultipleS_Log   multipleS_Log;

    if(!_current)
    {
        multipleS_Log.RefRecIdInventTable = _orig.RefRecId_InventTable;
    }
    else
    {
        multipleS_Log.RefRecIdInventTable = _current.RefRecId_InventTable;
    }

    if (_orig.RefRecId_CustTable != _current.RefRecId_CustTable)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::Customer;

        multipleS_Log.RangeValue        =  CustTable::findRecId(_current.RefRecId_CustTable).AccountNum;

        if (!_orig.RefRecId_CustTable)            // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.RefRecId_CustTable) // Löschung
        {
            multipleS_Log.RangeValue        = CustTable::findRecId(_orig.RefRecId_CustTable).AccountNum;
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                                // Änderung
        {
            multipleS_Log.RangeValue        += strFmt("@ApplicationFoundation:DocuDeletedRefCaptionGeneratorFromLabel", CustTable::findRecId(_orig.RefRecId_CustTable).AccountNum);
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

}
